globalThis.T1Lesson={"id":"s17x-t1-pipeline-leak","sceneId":"t1","methods":["ts"],"title":"管道泄漏智能检测：从正常关系到事件核查","version":"1.1.0","updated":"2026-10-24","tabs":{"background":{"label":"专业背景","lede":"输油管线两端的压力和流量会随负荷变化。先用正常运行学习出口应有的响应，再把持续偏差组合成待核查事件；与固定流量差、单压力规则放在同一测试运行上比较。","judge":[{"label":"数据","value":"教学合成","desc":"固定种子；专业来源单独列出"},{"label":"业务问题","value":"哪一段持续偏差值得优先核查？","desc":"展示算法如何帮助核查"}],"sections":[{"no":1,"en":"CONCEPT","title":"管线怎样被看见","html":"<p>图 B1｜入口与出口压力、流量是可观测量。图中没有推断的泄漏位置。</p><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"45\" y=\"38\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">一条管线，两端计量，多种工况</text><path d=\"M110 160H795\" stroke=\"#bfd1d9\" stroke-width=\"34\"/><path d=\"M110 160H795\" stroke=\"#147e84\" stroke-width=\"6\" stroke-dasharray=\"16 12\"/><rect x=\"46\" y=\"118\" width=\"83\" height=\"83\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"87.5\" y=\"166.5\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">泵</text><rect x=\"240\" y=\"60\" width=\"160\" height=\"58\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"320.0\" y=\"96.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">入口 P、Q</text><rect x=\"610\" y=\"60\" width=\"160\" height=\"58\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"690.0\" y=\"96.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">出口 P、Q</text><path d=\"M320 118L320 147\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"320\" cy=\"147\" r=\"5\" fill=\"#147e84\"/><path d=\"M690 118L690 147\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"690\" cy=\"147\" r=\"5\" fill=\"#147e84\"/><text x=\"235\" y=\"215\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">压力 MPa</text><text x=\"608\" y=\"215\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">流量 m³/h</text><text x=\"55\" y=\"272\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">泵速、负荷、阀门变化也会改变压力和流量；异常需要联系工况。</text></g></svg></div></div><figcaption>图 B1｜入口与出口压力、流量是可观测量。图中没有推断的泄漏位置。</figcaption></figure><p class=\"note\">比较流量前要统一体积参考状态、时间戳和采样间隔。液体管线在稳定库存下，入口与出口流量应近似平衡；启停或调阀期间管内库存也会变化，因此 Q入口−Q出口 不直接等于泄漏量。本例以 0.46×入口流量变化量模拟短时储存响应，未求解真实管线瞬态方程。压力残差提供另一条核查线索，不能单独定位泄漏。</p>"},{"no":2,"en":"CONCEPT","title":"负荷变化与泄漏响应有什么不同","html":"<p>图 B2｜概念曲线对比瞬态与持续损失，实际波形和事件由演示计算。</p><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"45\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">为什么一个固定阈值会看错？</text><text x=\"45\" y=\"90\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">流量</text><text x=\"45\" y=\"198\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">压力</text><path d=\"M140 115H850M140 230H850\" stroke=\"#cad8df\"/><path d=\"M140 103L260 98L280 66H440L460 100H620L640 105H850\" fill=\"none\" stroke=\"#147e84\" stroke-width=\"4\"/><path d=\"M140 108L260 104L280 91L300 69H440L460 112L480 104H620L640 135H780L800 106H850\" fill=\"none\" stroke=\"#bf793c\" stroke-width=\"4\"/><path d=\"M140 192L260 194L280 180H440L460 197H620L640 221H780L800 197H850\" fill=\"none\" stroke=\"#147e84\" stroke-width=\"4\"/><text x=\"260\" y=\"260\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">泵负荷变化</text><text x=\"640\" y=\"260\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">持续损失响应</text><text x=\"45\" y=\"295\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">概念曲线：先解释正常响应，再寻找两端无法共同解释的持续偏差。</text></g></svg></div></div><figcaption>图 B2｜概念曲线对比瞬态与持续损失，实际波形和事件由演示计算。</figcaption></figure>"},{"no":3,"en":"CONCEPT","title":"模型到底多学了什么","html":"<p>图 B3｜从正常运行学习流量与压力关系，用残差而非单个测值排序核查时段。</p><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"45\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">把正常关系变成一条可以核查的参照线</text><path d=\"M95 230H820M95 230V68\" stroke=\"#8097a5\"/><path d=\"M110 212L780 85\" stroke=\"#147e84\" stroke-width=\"4\"/><path d=\"M110 195L780 68L780 103L110 230Z\" fill=\"#147e84\" fill-opacity=\".12\"/><circle cx=\"140\" cy=\"205\" r=\"6\" fill=\"#147e84\"/><circle cx=\"215\" cy=\"188\" r=\"6\" fill=\"#147e84\"/><circle cx=\"280\" cy=\"175\" r=\"6\" fill=\"#147e84\"/><circle cx=\"370\" cy=\"160\" r=\"6\" fill=\"#147e84\"/><circle cx=\"470\" cy=\"145\" r=\"6\" fill=\"#147e84\"/><circle cx=\"550\" cy=\"128\" r=\"6\" fill=\"#147e84\"/><circle cx=\"630\" cy=\"113\" r=\"6\" fill=\"#147e84\"/><circle cx=\"715\" cy=\"100\" r=\"6\" fill=\"#147e84\"/><circle cx=\"620\" cy=\"185\" r=\"9\" fill=\"#bf793c\"/><path d=\"M620 117V179\" stroke=\"#bf793c\" stroke-width=\"3\" stroke-dasharray=\"5 4\"/><text x=\"640\" y=\"174\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">偏离正常关系</text><text x=\"100\" y=\"266\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">预测出口流量</text><text x=\"49\" y=\"61\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">实测出口流量</text><text x=\"45\" y=\"300\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">残差大只说明“不像正常”；传感器漂移也可能出现相似信号。</text></g></svg></div></div><figcaption>图 B3｜从正常运行学习流量与压力关系，用残差而非单个测值排序核查时段。</figcaption></figure><p>专业来源：<a href=\"https://www.phmsa.dot.gov/sites/phmsa.dot.gov/files/docs/technical-resources/pipeline/control-room-management/60341/ss0502ntsbscadastudy2005.pdf\" target=\"_blank\" rel=\"noreferrer\">NTSB / PHMSA：液体管线 SCADA 研究</a>。图形与教学合成数据由本案例制作。</p><p class=\"note\">分数把“正常模型预期−出口实测”的正向残差分别除以训练残差尺度，再合成无量纲量；它不是泄漏概率。先做3点因果平滑，再要求连续3点超阈才确认事件；图中的参考窗只在事后评价使用。</p>"}]},"workflow":{"label":"案例流程","title":"哪一段持续偏差值得优先核查？","lead":["输油管线两端的压力和流量会随负荷变化。先用正常运行学习出口应有的响应，再把持续偏差组合成待核查事件；与固定流量差、单压力规则放在同一测试运行上比较。"],"stats":[["数据性质","教学合成"],["默认实现","纯前端"],["核心方法","真实拟合与评价"]],"steps":[{"name":"先把传感器放在同一个时刻","role":"图 S1","do":"输入：两端 Q、P 和时间戳；动作：按 1 min 整理，计算入口 ΔQ。 见图 S1。","effect":"同单位、同时间轴的可观测序列。","trap":"时钟偏移会让一次负荷变化看起来像两端损失。"},{"name":"整条运行分组，不拆成随机点","role":"图 S2","do":"输入：18 条独立运行；动作：9 条正常运行训练、3 条验证、6 条测试。 见图 S2。","effect":"不会把同一负荷波形切碎后同时放入训练与测试。","trap":"验证事件用于选阈值，测试参考事件留到最后评价。"},{"name":"学会正常出口会怎样变化","role":"图 S3","do":"输入：正常训练运行；动作：拟合两个岭回归，学习训练均值、尺度和残差标准差。 见图 S3。","effect":"预期出口流量、预期出口压力和可对比残差。","trap":"传感器漂移同样会偏离正常关系；分数不是泄漏概率。"},{"name":"从偏差点合成待核查时段","role":"图 S4","do":"输入：验证分数；动作：选择阈值，因果 3 点均值后连续 3 点确认事件。 见图 S4。","effect":"保留确认起点、持续时间和实际超阈点数。","trap":"阈值倍率是测试探索条件；调低后可能同时增加命中和多报。"},{"name":"对齐事件，带着证据复核","role":"图 S5","do":"输入：模型、流差规则、单压力规则及独立参考窗；动作：按区间重叠一对一匹配，确认起点最多提前 2 min。 见图 S5。","effect":"同一分母下的事件 F1、延迟、正常小时多报及核查队列。","trap":"没有空间传感器依据，不从这些曲线推断精确泄漏位置。"}],"metrics":{"title":"逐步骤图解与计算口径","html":"<h3>图 S1｜先把传感器放在同一个时刻</h3><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S1 统一时钟与测点单位</text><text x=\"40\" y=\"86\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">入口流量</text><path d=\"M180 81L290 74L390 84L500 68L620 77L820 73\" stroke=\"#147e84\" fill=\"none\" stroke-width=\"3\"/><text x=\"40\" y=\"154\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">出口流量</text><path d=\"M180 149L290 142L390 152L500 136L620 145L820 141\" stroke=\"#bf793c\" fill=\"none\" stroke-width=\"3\"/><text x=\"40\" y=\"222\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">两端压力</text><path d=\"M180 217L290 210L390 220L500 204L620 213L820 209\" stroke=\"#657c91\" fill=\"none\" stroke-width=\"3\"/><path d=\"M500 57V255\" stroke=\"#263c4e\" stroke-dasharray=\"5 5\"/><text x=\"505\" y=\"285\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">同一分钟，再计算 ΔQ</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure><h3>图 S2｜整条运行分组，不拆成随机点</h3><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S2 按完整运行切分</text><text x=\"40\" y=\"97\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">训练：9 条正常运行</text><rect x=\"300\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"354\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"408\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"462\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"516\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"570\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"624\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"678\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"732\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><text x=\"40\" y=\"167\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">验证：3 条独立运行</text><rect x=\"300\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><rect x=\"354\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><rect x=\"408\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><text x=\"40\" y=\"237\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">测试：6 条独立运行</text><rect x=\"300\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"354\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"408\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"462\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"516\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"570\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure><h3>图 S3｜学会正常出口会怎样变化</h3><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S3 两个出口预测，统一成残差尺度</text><rect x=\"45\" y=\"80\" width=\"230\" height=\"80\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"160.0\" y=\"127.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">Q入、P入、ΔQ</text><path d=\"M280 120L345 120\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"345\" cy=\"120\" r=\"5\" fill=\"#147e84\"/><rect x=\"350\" y=\"80\" width=\"225\" height=\"80\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"462.5\" y=\"127.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">岭回归正常模型</text><path d=\"M580 120L640 120\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"640\" cy=\"120\" r=\"5\" fill=\"#147e84\"/><rect x=\"645\" y=\"67\" width=\"210\" height=\"55\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"750.0\" y=\"101.5\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">预期 Q出</text><rect x=\"645\" y=\"135\" width=\"210\" height=\"55\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"750.0\" y=\"169.5\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">预期 P出</text><text x=\"55\" y=\"240\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">用训练残差标准差缩放，两类物理单位才能共同进入一个分数。</text><text x=\"55\" y=\"278\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">模型只读仪表数据；没有泄漏参考标签作为输入。</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure><h3>图 S4｜从偏差点合成待核查时段</h3><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S4 验证选择阈值，连续 3 点再确认</text><path d=\"M80 215H830M80 130H830\" stroke=\"#bf793c\" stroke-dasharray=\"7 5\"/><path d=\"M80 204L180 195L240 105L260 198L410 198L450 110L480 98L510 94L540 90L570 93L610 197H830\" stroke=\"#147e84\" fill=\"none\" stroke-width=\"4\"/><text x=\"180\" y=\"258\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">单点尖峰未确认</text><text x=\"470\" y=\"258\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">持续偏差 → 事件</text><text x=\"640\" y=\"115\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">阈值</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure><h3>图 S5｜对齐事件，带着证据复核</h3><figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S5 每个候选与参考最多匹配一次</text><text x=\"40\" y=\"100\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">参考窗</text><text x=\"40\" y=\"185\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">候选窗</text><rect x=\"230\" y=\"70\" width=\"210\" height=\"35\" rx=\"5\" fill=\"#d4e1e7\"/><rect x=\"620\" y=\"70\" width=\"130\" height=\"35\" rx=\"5\" fill=\"#d4e1e7\"/><rect x=\"250\" y=\"155\" width=\"155\" height=\"35\" rx=\"5\" fill=\"#147e84\"/><rect x=\"450\" y=\"155\" width=\"65\" height=\"35\" rx=\"5\" fill=\"#bf793c\"/><path d=\"M330 110L330 148\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"330\" cy=\"148\" r=\"5\" fill=\"#147e84\"/><text x=\"237\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">命中 1</text><text x=\"442\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">多报 1</text><text x=\"620\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">漏检 1</text><text x=\"40\" y=\"281\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">图为计数示例；演示从实际事件窗计算 F1、延迟和正常小时多报。</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure><p>模型、基线共用测试分母，评价参考不进入预测。输入变化后需重算，空分母显示不适用，人工复核意见与原始计算分开保存。</p>"},"fails":[{"name":"从偏差点合成待核查时段","why":"阈值倍率是测试探索条件；调低后可能同时增加命中和多报。"},{"name":"对齐事件，带着证据复核","why":"没有空间传感器依据，不从这些曲线推断精确泄漏位置。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","label":"可运行示范","intro":"输油管线两端的压力和流量会随负荷变化。先用正常运行学习出口应有的响应，再把持续偏差组合成待核查事件；与固定流量差、单压力规则放在同一测试运行上比较。","height":1100}},"stepFigures":["<figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S1 统一时钟与测点单位</text><text x=\"40\" y=\"86\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">入口流量</text><path d=\"M180 81L290 74L390 84L500 68L620 77L820 73\" stroke=\"#147e84\" fill=\"none\" stroke-width=\"3\"/><text x=\"40\" y=\"154\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">出口流量</text><path d=\"M180 149L290 142L390 152L500 136L620 145L820 141\" stroke=\"#bf793c\" fill=\"none\" stroke-width=\"3\"/><text x=\"40\" y=\"222\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">两端压力</text><path d=\"M180 217L290 210L390 220L500 204L620 213L820 209\" stroke=\"#657c91\" fill=\"none\" stroke-width=\"3\"/><path d=\"M500 57V255\" stroke=\"#263c4e\" stroke-dasharray=\"5 5\"/><text x=\"505\" y=\"285\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">同一分钟，再计算 ΔQ</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure>","<figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S2 按完整运行切分</text><text x=\"40\" y=\"97\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">训练：9 条正常运行</text><rect x=\"300\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"354\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"408\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"462\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"516\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"570\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"624\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"678\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><rect x=\"732\" y=\"70\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#147e84\"/><text x=\"40\" y=\"167\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">验证：3 条独立运行</text><rect x=\"300\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><rect x=\"354\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><rect x=\"408\" y=\"140\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#bf793c\"/><text x=\"40\" y=\"237\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">测试：6 条独立运行</text><rect x=\"300\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"354\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"408\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"462\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"516\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/><rect x=\"570\" y=\"210\" width=\"43\" height=\"38\" rx=\"5\" fill=\"#657c91\"/></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure>","<figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S3 两个出口预测，统一成残差尺度</text><rect x=\"45\" y=\"80\" width=\"230\" height=\"80\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"160.0\" y=\"127.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">Q入、P入、ΔQ</text><path d=\"M280 120L345 120\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"345\" cy=\"120\" r=\"5\" fill=\"#147e84\"/><rect x=\"350\" y=\"80\" width=\"225\" height=\"80\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"462.5\" y=\"127.0\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">岭回归正常模型</text><path d=\"M580 120L640 120\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"640\" cy=\"120\" r=\"5\" fill=\"#147e84\"/><rect x=\"645\" y=\"67\" width=\"210\" height=\"55\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"750.0\" y=\"101.5\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">预期 Q出</text><rect x=\"645\" y=\"135\" width=\"210\" height=\"55\" rx=\"10\" fill=\"#deedf0\" stroke=\"#b8ccd5\"/><text x=\"750.0\" y=\"169.5\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"middle\">预期 P出</text><text x=\"55\" y=\"240\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">用训练残差标准差缩放，两类物理单位才能共同进入一个分数。</text><text x=\"55\" y=\"278\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">模型只读仪表数据；没有泄漏参考标签作为输入。</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure>","<figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S4 验证选择阈值，连续 3 点再确认</text><path d=\"M80 215H830M80 130H830\" stroke=\"#bf793c\" stroke-dasharray=\"7 5\"/><path d=\"M80 204L180 195L240 105L260 198L410 198L450 110L480 98L510 94L540 90L570 93L610 197H830\" stroke=\"#147e84\" fill=\"none\" stroke-width=\"4\"/><text x=\"180\" y=\"258\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">单点尖峰未确认</text><text x=\"470\" y=\"258\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">持续偏差 → 事件</text><text x=\"640\" y=\"115\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">阈值</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure>","<figure><div class=\"diagram\" tabindex=\"0\" style=\"overflow-x:auto;max-width:100%\"><div style=\"min-width:680px\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 900 310\" role=\"img\" aria-label=\"专业概念图\"><rect width=\"900\" height=\"310\" rx=\"18\" fill=\"#f1f5f6\"/><g font-family=\"system-ui,Microsoft YaHei,sans-serif\" font-size=\"20\" fill=\"#263c4e\"><text x=\"40\" y=\"35\" fill=\"#263c4e\" font-size=\"20\" text-anchor=\"start\">S5 每个候选与参考最多匹配一次</text><text x=\"40\" y=\"100\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">参考窗</text><text x=\"40\" y=\"185\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">候选窗</text><rect x=\"230\" y=\"70\" width=\"210\" height=\"35\" rx=\"5\" fill=\"#d4e1e7\"/><rect x=\"620\" y=\"70\" width=\"130\" height=\"35\" rx=\"5\" fill=\"#d4e1e7\"/><rect x=\"250\" y=\"155\" width=\"155\" height=\"35\" rx=\"5\" fill=\"#147e84\"/><rect x=\"450\" y=\"155\" width=\"65\" height=\"35\" rx=\"5\" fill=\"#bf793c\"/><path d=\"M330 110L330 148\" fill=\"none\" stroke=\"#6a8c9a\" stroke-width=\"3\"/><circle cx=\"330\" cy=\"148\" r=\"5\" fill=\"#147e84\"/><text x=\"237\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">命中 1</text><text x=\"442\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">多报 1</text><text x=\"620\" y=\"232\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">漏检 1</text><text x=\"40\" y=\"281\" fill=\"#263c4e\" font-size=\"18\" text-anchor=\"start\">图为计数示例；演示从实际事件窗计算 F1、延迟和正常小时多报。</text></g></svg></div></div><figcaption>输入、动作与产物见本步骤文字；概念图用于解释，实际指标在示范中重算。</figcaption></figure>"]};
(function(){
'use strict';
const E=globalThis.T1Core,L=globalThis.T1Lesson,$=s=>document.querySelector(s);let result=null,status='idle',runId=0,inputRevision=0;const reviews=[];
const fmt=(n,d=2)=>n==null?'不适用':Number(n).toFixed(d),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderReviews(){if(!$('#review-history'))return;$('#review-history').textContent=reviews.length?reviews.map(r=>'运行 '+r.runId+' / 输入修订 '+r.inputRevision+' · '+(r.runId===runId&&r.inputRevision===inputRevision&&status==='complete'?'当前确认':'历史确认，当前需重核')+'：'+r.note).join('\n'):'尚无人工确认。';}
function invalidate(){inputRevision++;$('#review-message').textContent='输入已变更，当前结果需重新计算与复核。';if($('#review-confirm'))$('#review-confirm').checked=false;renderReviews();}
function contentVersion(value){const text=JSON.stringify(value);let h=2166136261;for(let i=0;i<text.length;i++){h^=text.charCodeAt(i);h=Math.imul(h,16777619);}return 'fnv1a32-'+(h>>>0).toString(16);}
function envelope(){const observations='t1'==='t1'?result.prediction.trace.map(r=>({group:r.group,minute:r.minute,qIn:r.qIn,qOut:r.qOut,pIn:r.pIn,pOut:r.pOut,dq:r.dq})):result.prediction.map(r=>({group:r.group,minute:r.minute,sourceMinute:r.sourceMinute,process:r.x,lastLab:r.lastLab,lastLabSample:r.lastLabSample,lastLabRelease:r.lastLabRelease})),sourceVersion=contentVersion(observations),sourceRecordId='t1'+'-observable-series',currentReview=reviews.filter(r=>r.runId===runId&&r.inputRevision===inputRevision),sourceRefs=selector=>[{sourceRecordId,sourceVersion,selector}],claims='t1'==='t1'?result.prediction.events.map((e,i)=>({claimId:'t1'+'-claim-'+(i+1),revision:inputRevision+1,kind:'model_inference',statement:e.group+' 在 '+e.start+'–'+e.end+' min 检出持续偏差，列入核查队列。',sourceRefs:sourceRefs({type:'time_range',group:e.group,timeRange_s:[e.firstCross*60,e.end*60],sourceTimeUnit:'min'}),reviewStatus:currentReview.length?'confirmed':'needs_review',traceabilityStatus:'linked',supportStatus:currentReview.length?'human_verified':'unchecked',reviewHistory:currentReview})):result.split.test.map((group,i)=>({claimId:'t1'+'-claim-'+(i+1),revision:inputRevision+1,kind:'model_inference',statement:group+' 已计算逐分钟密度估计，见对应预测序列与独立评价。',sourceRefs:sourceRefs({type:'time_range',group,timeRange_s:[Math.min(...result.prediction.filter(p=>p.group===group).map(p=>p.minute))*60,(Math.max(...result.prediction.filter(p=>p.group===group).map(p=>p.minute))+1)*60],sourceTimeUnit:'min'}),reviewStatus:currentReview.length?'confirmed':'needs_review',traceabilityStatus:'linked',supportStatus:currentReview.length?'human_verified':'unchecked',reviewHistory:currentReview}));return {schemaVersion:'1.0',caseId:result.caseId,caseVersion:"1.1.0",runId,datasetId:result.dataVersion+'-'+contentVersion(result.params),wellId:null,assetId:'t1'==='t1'?'PIPE-017':'UNIT-017',dataNature:'synthetic_teaching',state:'ready',status,sourceVersion,runConfig:{seed:result.params.seed,dataVersion:result.dataVersion,splitDescription:result.split,method:'t1'==='t1'?'normal-ridge-residual-events':'ridge-quality-softsensor',parameters:params(),inputRevision},sources:[{sourceRecordId,sourceVersion,sourceType:'series_segment',content:{units:'t1'==='t1'?{flow:'m³/h',pressure:'MPa',time:'min'}:{temperature:'°C',pressure:'MPa',flow:'m³/h',density:'kg/m³',time:'min'},observations}}],claims,limitations:'t1'==='t1'?['合成工况用于解释正常关系与异常核查。','未由空间测点推断泄漏位置，异常解释需核对泵阀和仪表。']:['合成过程与密度用于解释软测量。','时间常数为教学设置；原料关系或仪表漂移需要补充化验。'],reviews:reviews.slice(),metrics:result.metrics,result,createdAt:new Date().toISOString()};}
function params(){return {scenario:$('#scenario').value,severity:+$('#severity').value,noise:+$('#noise').value,sensitivity:+$('#sensitivity').value,flowThreshold:5,seed:1701};}
function setStatus(s,text){status=s;$('#status').textContent=text;$('#status').dataset.state=s;$('#export').disabled=s!=='complete';$('#review-save').disabled=s!=='complete';$('#outputs').classList.toggle('stale',s==='stale');renderReviews();}
function svg(body,h=300){return `<svg viewBox="0 0 900 ${h}" role="img" xmlns="http://www.w3.org/2000/svg"><g font-family="system-ui,Microsoft YaHei,sans-serif" font-size="18" fill="#263c4e">${body}</g></svg>`;}
function line(rows,key,x,y,color,dash=''){return `<path d="${rows.map((r,i)=>(i?'L':'M')+x(r).toFixed(1)+','+y(r[key]).toFixed(1)).join(' ')}" fill="none" stroke="${color}" stroke-width="3" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;}
function chart(rows,keys,labels,title){const lo=Math.min(...rows.flatMap(r=>keys.map(k=>r[k]))),hi=Math.max(...rows.flatMap(r=>keys.map(k=>r[k]))),range=Math.max(.1,hi-lo),x=r=>65+r.localMinute/95*800,y=v=>225-(v-lo)/range*155;let b=`<text x="65" y="30" font-weight="700">${title}</text>`;[0,.5,1].forEach(v=>{const yy=225-v*155;b+=`<path d="M65 ${yy}H865" stroke="#dce5e9"/><text x="6" y="${yy+6}">${fmt(lo+range*v,1)}</text>`;});[0,20,40,60,80,95].forEach(t=>b+=`<text x="${65+t/95*800}" y="255" text-anchor="middle">${t}</text>`);keys.forEach((k,i)=>b+=line(rows,k,x,y,['#147e84','#bf793c','#64788e'][i],i===2?'7 5':''));b+=`<text x="865" y="283" text-anchor="end">运行内时间 / min</text>`;return svg(b)+`<div class="legend">${labels.map((s,i)=>`<span style="--dot:${['#147e84','#bf793c','#64788e'][i]}">${s}</span>`).join('')}</div>`;}
function eventsChart(rows,events,threshold,truth){const ymax=Math.max(threshold*1.2,...rows.map(r=>r.score)),x=v=>65+v/95*800,y=v=>215-v/ymax*145;let b='<text x="65" y="29" font-weight="700">残差分数与确认后的事件窗</text>';[0,.5,1].forEach(f=>b+=`<path d="M65 ${215-f*145}H865" stroke="#dce5e9"/><text x="8" y="${220-f*145}">${fmt(ymax*f,1)}</text>`);[0,20,40,60,80,95].forEach(t=>b+=`<text x="${x(t)}" y="267" text-anchor="middle">${t}</text>`);if($('#show-truth').checked)truth.forEach(t=>{const a=t.start-rows[0].minute,z=t.end-rows[0].minute;b+=`<rect x="${x(a)}" y="65" width="${x(z)-x(a)}" height="155" fill="#d9e4e9"/><text x="${x(a)+4}" y="88" font-size="16">参考窗</text>`;});b+=`<path d="M65 ${y(threshold)}H865" stroke="#bd783b" stroke-width="2" stroke-dasharray="7 5"/><text x="650" y="${Math.max(54,y(threshold)-9)}" fill="#9b5e28">阈值 ${fmt(threshold,1)}</text>`+line(rows,'score',r=>x(r.localMinute),y,'#147e84');events.forEach(e=>b+=`<rect x="${x(e.start-rows[0].minute)}" y="235" width="${Math.max(4,x(e.end-rows[0].minute)-x(e.start-rows[0].minute))}" height="13" rx="3" fill="#147e84"/>`);b+='<text x="65" y="280">时间 / min；事件条从连续3点确认起算；分数无量纲。</text>';return svg(b);}
function draw(){if(!result)return;const group=$('#run-group').value,rows=result.prediction.trace.filter(r=>r.group===group);$('#pipeline-now').innerHTML=svg(`<path d="M100 105H800" stroke="#c2d6dc" stroke-width="28"/><path d="M100 105H800" stroke="#187e84" stroke-width="5" stroke-dasharray="12 8"/><circle cx="130" cy="105" r="28" fill="#fff" stroke="#187e84" stroke-width="4"/><circle cx="770" cy="105" r="28" fill="#fff" stroke="#187e84" stroke-width="4"/><text x="130" y="52" text-anchor="middle">入口计量</text><text x="770" y="52" text-anchor="middle">出口计量</text><text x="130" y="170" text-anchor="middle">${fmt(E.mean(rows.map(r=>r.qIn)),1)} m³/h</text><text x="770" y="170" text-anchor="middle">${fmt(E.mean(rows.map(r=>r.qOut)),1)} m³/h</text><text x="450" y="220" text-anchor="middle">${esc(group)} · 显示 96 min 均值；不推断泄漏位置</text>`,250);$('#flow-chart').innerHTML=chart(rows,['qIn','qOut','expectedQ'],['入口实测','出口实测','正常模型预期出口'],'流量 / m³·h⁻¹');$('#pressure-chart').innerHTML=chart(rows,['pIn','pOut','expectedP'],['入口实测','出口实测','正常模型预期出口'],'压力 / MPa');$('#event-chart').innerHTML=eventsChart(rows,result.prediction.events.filter(e=>e.group===group),result.threshold,result.evaluationTruth.filter(t=>t.group===group));const ms=result.metrics;$('#metric-table').innerHTML=`<table><thead><tr><th>同一测试运行</th><th>事件 F1</th><th>命中 / 参考</th><th>多报事件</th><th>平均延迟 min</th><th>多报 / 正常 h</th></tr></thead><tbody>${[['model','学习正常关系'],['baseline','固定流量差 ≥ 5 m³/h'],['pressure','固定出口压力 < 5.82 MPa']].map(([key,name])=>{const m=ms[key];return `<tr><th>${name}</th><td>${fmt(m.f1,3)}</td><td>${m.tp} / ${m.truthCount}</td><td>${m.fp} / ${m.candidateCount} 候选</td><td>${fmt(m.delay_min,1)}</td><td>${fmt(m.falseEventsPerHour,3)}</td></tr>`;}).join('')}</tbody></table><p>模型事件 F1 = 2×${ms.model.tp} / (${ms.model.candidateCount}+${ms.model.truthCount})；正常时间 ${ms.model.normalMinutes} min。事件窗须重叠，候选确认起点最多提前 2 min，长时间既有告警不自动算命中。没有参考事件时召回显示“不适用”。</p>`;$('#split-info').innerHTML=`<b>9 / 3 / 6 条独立运行</b><p>训练 ${result.split.trainRows} 点（只含正常运行）；验证 ${result.split.validationRows} 点；测试 ${result.split.testRows} 点。验证选择阈值 ${fmt(result.selection.threshold,1)}，当前倍率 ${fmt(params().sensitivity,2)}。</p><p>训练残差尺度：流量 ${fmt(result.model.residualScale[0],3)} m³/h，压力 ${fmt(result.model.residualScale[1],4)} MPa。输入是入口流量、入口压力和可观测流量变化；测试参考事件只用于最后评价。</p>`;const pe=result.prediction.events;$('#event-list').innerHTML=pe.length?`<table><thead><tr><th>待核查运行</th><th>确认窗 / min</th><th>连续超阈点数</th></tr></thead><tbody>${pe.map(e=>`<tr><td>${e.group}</td><td>${e.start%120}–${e.end%120}</td><td>${e.confirmedSamples}</td></tr>`).join('')}</tbody></table>`:'<p>当前阈值下没有确认事件。可以降低阈值倍率，观察召回与多报的变化。</p>';}
function run(){$('#review-message').textContent='本轮计算完成后，需重新核对当前来源。';setStatus('running','正在拟合正常模型、用验证运行选阈值并计算测试事件…');try{result=E.run(params());runId++;$('#run-group').innerHTML=result.split.test.map(id=>`<option>${id}</option>`).join('');if($('#review-confirm'))$('#review-confirm').checked=false;setStatus('complete','计算完成 · 教学合成数据 · 当前参数与结果一致');draw();}catch(e){setStatus('error','计算失败：'+e.message);}}
function lesson(){const b=L.tabs.background,w=L.tabs.workflow;$('#background-content').innerHTML=b.sections.map(s=>`<article class="chapter"><div class="kicker">BACKGROUND ${s.no}</div><h2>${s.title}</h2>${s.html}</article>`).join('');$('#workflow-content').innerHTML=w.steps.map((s,i)=>`<article class="chapter"><div class="step-label">${String(i+1).padStart(2,'0')} / ${w.steps.length}</div><h2>${s.name}</h2><p>${s.do}</p><p><b>得到：</b>${s.effect}</p><p class="note">留意：${s.trap}</p>${L.stepFigures[i]}</article>`).join('');}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{for(const id of ['background','workflow','lab'])$('#'+id).hidden=id!==b.dataset.tab;document.querySelectorAll('nav [data-tab]').forEach(v=>v.setAttribute('aria-pressed',String(v.dataset.tab===b.dataset.tab)));}));$('#run').addEventListener('click',run);$('#reset').addEventListener('click',()=>{$('#scenario').value='normal';$('#severity').value=7;$('#noise').value=1;$('#sensitivity').value=1;invalidate();sync();run();});function sync(){['severity','noise','sensitivity'].forEach(id=>$('#'+id+'-value').textContent=$('#'+id).value);}document.querySelectorAll('[data-param]').forEach(input=>input.addEventListener('input',()=>{invalidate();sync();if(result)setStatus('stale','条件已改变 · 请重新运行，当前图表保留上一轮结果');}));$('#scenario').addEventListener('change',()=>{invalidate();if($('#scenario').value==='tiny')$('#severity').value=1.2;else $('#severity').value=7;sync();if(result)setStatus('stale','情景已改变 · 重新运行后查看当前结果');});$('#run-group').addEventListener('change',()=>{if(status==='complete')draw();});$('#show-truth').addEventListener('change',()=>{if(status==='complete')draw();});$('#review-save').addEventListener('click',()=>{if(!$('#review-confirm').checked||!$('#review-note').value.trim()){ $('#review-message').textContent='先勾选核对声明并填写具体依据。';return;}reviews.push({runId,inputRevision,reviewStatus:'confirmed',traceabilityStatus:'linked',supportStatus:'human_verified',sourceVersion:envelope().sourceVersion,note:$('#review-note').value.trim(),at:new Date().toISOString()});$('#review-message').textContent='已保存当前运行的人工确认。';renderReviews();});$('#export').addEventListener('click',()=>{if(status!=='complete')return;const record=envelope(),blob=new Blob([JSON.stringify(record,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='t1-pipeline-leak-run-'+runId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});globalThis.CaseInspect={snapshot:()=>({sceneId:'t1',caseId:'s17x-t1-pipeline-leak',status,metrics:result?.metrics??null,runId,params:params()})};lesson();sync();
})();

(function(g){'use strict';
function mount(root=document){root.querySelectorAll('.case-flow-overview').forEach(chart=>{
 if(chart.dataset.flowMounted)return;chart.dataset.flowMounted='true';
 const area=chart.closest('#workflow')||chart.closest('main')||root;
 const targets=()=>[...area.querySelectorAll('[data-sr-step],[data-step]')].filter(e=>!e.closest('.case-flow-overview'));
 const chapters=()=>area.querySelectorAll('#workflow-content>article,.flow-step,.workflow-step');
 const select=n=>{chart.querySelectorAll('[data-flow-step]').forEach(el=>el.setAttribute('aria-current',String(+el.dataset.flowStep===n)));};
 const go=el=>{const n=+el.dataset.flowStep,b=targets().find(b=>+(b.dataset.srStep??b.dataset.step)===n);if(b)b.click();else chapters()[n]?.scrollIntoView({block:'start',behavior:'auto'});select(n);};
 chart.querySelectorAll('[data-flow-step]').forEach(el=>{el.setAttribute('role','button');el.setAttribute('tabindex','0');el.setAttribute('aria-label','查看步骤 '+(+el.dataset.flowStep+1)+'：'+el.textContent.trim());});
 chart.querySelector('[data-flow-instruction]').textContent=' 点击图中节点，可查看对应步骤。';
 chart.addEventListener('click',e=>{const el=e.target.closest('[data-flow-step]');if(el)go(el);});
 chart.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-flow-step]')){e.preventDefault();go(e.target);}});
 area.addEventListener('click',e=>{const b=e.target.closest('[data-sr-step],[data-step]');if(b)select(+(b.dataset.srStep??b.dataset.step));});
 const current=targets().find(b=>b.matches('[aria-selected=true],[aria-pressed=true],.active'));select(+(current?.dataset.srStep??current?.dataset.step??0));
 });}
g.S17Flow={mount};
})(globalThis);

